// CabStates are the state variables for wave equations on
// a wave state with a single complex value,
// where A = real and B = complex components.
//
// Based on [EMStates] so the complex KG wave can be coupled to the
// electromagnetic field: the A0 / A potentials it is pushed by, and the
// Charge / Current it drives them with, are the same variables MaxwellKernel
// uses. Params.EM switches the coupling on.
type CabStates EMStates //enums:enum -trim-prefix=Cab

const (
	// CabAs is the wave state variable for component A: real.
	CabAs CabStates = CabStates(EMStatesN) + iota

	// CabBs is the wave state variable for component B: imaginary.
	CabBs

	// CabAv is the velocity of wave state variable A.
	CabAv

	// CabBv is the velocity of wave state variable B.
	CabBv

	// CabV is an external potential energy factor, that
	// can be used to push particles around.
	CabV

	// CabMag is the state magnitude (state * complex conjugate),
	// which represents the total probability or a conserved
	// charge value.
	CabMag
)

// KleinGordonKernel is the kernel for computing the KleinGordon equations,
// on scalar state values (WaveStates).
func KleinGordonKernel(i uint32) { //gosl:kernel
	ctx := GetCtx(0)
	var x, y, z int32
	ok := ctx.StateCoords(i, &x, &y, &z)
	if !ok {
		return
	}
	cur := ctx.CurState
	prv := ctx.PrevState()
	ppos := State.Value(int(z), int(y), int(x), int(WavePos), int(prv))
	pvel := State.Value(int(z), int(y), int(x), int(WaveVel), int(prv))
	vpot := State.Value(int(z), int(y), int(x), int(WaveV), int(prv))

	mhsq := Params[0].MOverHSq
	csq := Params[0].CSq

	var force float32
	if Params[0].ThreeD.IsTrue() {
		force = Laplacian19(x, y, z, int32(WavePos), prv, ppos)
	} else {
		force = Laplacian1D(x, y, z, int32(WavePos), prv, ppos)
	}
	force += (vpot - mhsq) * ppos // this is the only diff from standard Wave
	vel := pvel + csq*force
	pos := ppos + vel

	if Params[0].Energy.IsTrue() {
		midVel := 0.5 * (pvel + vel)
		kinetic := Params[0].Inv2CSq * midVel * midVel
		var potential float32
		if Params[0].ThreeD.IsTrue() {
			potential = PotentialEnergy19(x, y, z, int32(WavePos), prv, ppos)
		} else {
			potential = PotentialEnergy1D(x, y, z, int32(WavePos), prv, ppos)
		}

		State.Set(kinetic, int(z), int(y), int(x), int(WaveKinetic), int(cur))
		State.Set(potential, int(z), int(y), int(x), int(WavePotential), int(cur))
		State.Set(kinetic+potential, int(z), int(y), int(x), int(WaveEnergy), int(cur))
	}
	State.Set(force, int(z), int(y), int(x), int(WaveForce), int(cur))
	State.Set(vel, int(z), int(y), int(x), int(WaveVel), int(cur))
	State.Set(pos, int(z), int(y), int(x), int(WavePos), int(cur))
}

// KleinGordonCKernel is the kernel for the complex Klein-Gordon equation, with
// optional minimal coupling to the electromagnetic field (Params.EM).
//
// Uncoupled, the two components evolve as two independent real KG waves: the
// complex structure only shows up in the conserved charge, which needs both.
//
// Coupled, the covariant derivative D = d - i(e/hbar)A adds three terms:
//
//	dd(phi_a) = c^2 (Lap - mhsq) phi_a + (2e/hbar)(A0 d(phi_b) + c A.grad phi_b) + (e^2/hbar^2)(A0^2 - A^2) phi_a
//	dd(phi_b) = c^2 (Lap - mhsq) phi_b - (2e/hbar)(A0 d(phi_a) + c A.grad phi_a) + (e^2/hbar^2)(A0^2 - A^2) phi_b
//
// The A0 term acts on the VELOCITY with opposite signs on the two components,
// which is a rotation of (d phi_a, d phi_b) at rate 2 e A0 / hbar. An explicit
// integrator does not rotate, it spirals, and the charge runs away -- which is
// the instability described in web/content/complex-kg.md. Params.Boris applies
// the rotation exactly instead. See EWBorisPhase for the same problem in the
// electroweak kernel.
//
// It also writes the [Charge] and [Current] that MaxwellKernel reads, so the
// wave and the field drive each other.
func KleinGordonCKernel(i uint32) { //gosl:kernel
	ctx := GetCtx(0)
	var x, y, z int32
	ok := ctx.StateCoords(i, &x, &y, &z)
	if !ok {
		return
	}
	cur := ctx.CurState
	prv := ctx.PrevState()
	pposA := State.Value(int(z), int(y), int(x), int(CabAs), int(prv))
	pposB := State.Value(int(z), int(y), int(x), int(CabBs), int(prv))
	pvelA := State.Value(int(z), int(y), int(x), int(CabAv), int(prv))
	pvelB := State.Value(int(z), int(y), int(x), int(CabBv), int(prv))
	vpot := State.Value(int(z), int(y), int(x), int(CabV), int(prv))

	mhsq := Params[0].MOverHSq
	csq := Params[0].CSq
	threeD := Params[0].ThreeD.IsTrue()

	var forceA, forceB float32
	if threeD {
		forceA = Laplacian19(x, y, z, int32(CabAs), prv, pposA)
		forceB = Laplacian19(x, y, z, int32(CabBs), prv, pposB)
	} else {
		forceA = Laplacian1D(x, y, z, int32(CabAs), prv, pposA)
		forceB = Laplacian1D(x, y, z, int32(CabBs), prv, pposB)
	}
	forceA += (vpot - mhsq) * pposA // this is the only diff from standard Wave
	forceB += (vpot - mhsq) * pposB
	accA := csq * forceA
	accB := csq * forceB

	// needed for the current in any case, and for the A.grad term when coupled
	var gA, gB math32.Vector3
	if threeD {
		gA = Gradient10(x, y, z, int32(CabAs), prv)
		gB = Gradient10(x, y, z, int32(CabBs), prv)
	} else {
		gA = Gradient1D(x, y, z, int32(CabAs), prv)
		gB = Gradient1D(x, y, z, int32(CabBs), prv)
	}

	em := Params[0].EM.IsTrue()
	var a0, ax, ay, az, omega float32
	if em {
		a0 = State.Value(int(z), int(y), int(x), int(A0s), int(prv))
		ax = State.Value(int(z), int(y), int(x), int(AXs), int(prv))
		ay = State.Value(int(z), int(y), int(x), int(AYs), int(prv))
		az = State.Value(int(z), int(y), int(x), int(AZs), int(prv))
		e2h := Params[0].E2OverH
		cc := Params[0].C
		asq := a0*a0 - (ax*ax + ay*ay + az*az)
		eh2 := Params[0].EOverHSq * asq
		accA += e2h*cc*(ax*gB.X+ay*gB.Y+az*gB.Z) + eh2*pposA
		accB += -e2h*cc*(ax*gA.X+ay*gA.Y+az*gA.Z) + eh2*pposB
		omega = e2h * a0 // the A0 rotation rate
	}

	var velA, velB float32
	if em && Params[0].Boris.IsTrue() {
		// half kick, exact rotation, half kick. d(v_a + i v_b)/dt =
		// -i omega (v_a + i v_b), so the velocity turns by -omega per step.
		haA := 0.5 * accA
		haB := 0.5 * accB
		mA := pvelA + haA
		mB := pvelB + haB
		cs := math32.Cos(omega)
		sn := math32.Sin(omega)
		velA = cs*mA + sn*mB + haA
		velB = -sn*mA + cs*mB + haB
	} else {
		velA = pvelA + accA + omega*pvelB
		velB = pvelB + accB - omega*pvelA
	}
	posA := pposA + velA
	posB := pposB + velB

	// charge and current, at the same time as the position they use: the
	// midpoint velocity is the one that belongs with the previous position in
	// a leapfrog, and the gradients are of the previous position too.
	midA := 0.5 * (pvelA + velA)
	midB := 0.5 * (pvelB + velB)
	ccm := pposA*pposA + pposB*pposB
	hem := Params[0].HEOverMCSq // hbar e / (m c^2)
	rho := hem * (pposB*midA - pposA*midB)
	if em {
		rho -= Params[0].EsqOverMCSq * a0 * ccm
	}
	jf := hem * csq // hbar e / m
	jx := jf * (pposA*gB.X - pposB*gA.X)
	jy := jf * (pposA*gB.Y - pposB*gA.Y)
	jz := jf * (pposA*gB.Z - pposB*gA.Z)
	if em {
		ja := Params[0].EsqOverMCSq * Params[0].C * ccm
		jx -= ja * ax
		jy -= ja * ay
		jz -= ja * az
	}
	State.Set(rho, int(z), int(y), int(x), int(Charge), int(cur))
	State.Set(jx, int(z), int(y), int(x), int(CurrentX), int(cur))
	State.Set(jy, int(z), int(y), int(x), int(CurrentY), int(cur))
	State.Set(jz, int(z), int(y), int(x), int(CurrentZ), int(cur))

	// ccm, not the new position: Charge, Current and Mag are all diagnostics
	// of the same instant, the one the midpoint velocity belongs to. Reading
	// Mag a step later than Charge breaks rho = -e |chi|^2 by the amount the
	// Laplacian moves |chi|^2 in one step.
	State.Set(ccm, int(z), int(y), int(x), int(CabMag), int(cur))
	State.Set(velA, int(z), int(y), int(x), int(CabAv), int(cur))
	State.Set(posA, int(z), int(y), int(x), int(CabAs), int(cur))

	State.Set(velB, int(z), int(y), int(x), int(CabBv), int(cur))
	State.Set(posB, int(z), int(y), int(x), int(CabBs), int(cur))
}

// KleinGordonDampKernel is the kernel for computing the KleinGordon equations,
// on scalar state values (WaveStates),
// at damped edges. Does Sommerfield damping where velocity = force.
func KleinGordonDampKernel(i uint32) { //gosl:kernel
	ctx := GetCtx(0)
	var x, y, z int32
	face := ctx.EdgeCoords(i, &x, &y, &z)
	if face < 0 {
		return
	}
	sz := ctx.SizePlus1() // exclude updating on edges
	cur := ctx.CurState
	prv := ctx.PrevState()
	ppos := State.Value(int(z), int(y), int(x), int(WavePos), int(prv))

	mhsq := Params[0].MOverHSq
	csq := Params[0].CSq

	var force float32
	if Params[0].ThreeD.IsTrue() {
		force = LaplacianEdge19(x, y, z, sz.X, sz.Y, sz.Z, int32(WavePos), prv, ppos)
	} else {
		force = LaplacianEdge1D(x, y, z, sz.X, sz.Y, sz.Z, int32(WavePos), prv, ppos)
	}
	force -= mhsq * ppos // this is the only diff from standard Wave
	vel := csq * force   // key damp: no +=
	pos := ppos + vel

	State.Set(force, int(z), int(y), int(x), int(WaveForce), int(cur))
	State.Set(vel, int(z), int(y), int(x), int(WaveVel), int(cur))
	State.Set(pos, int(z), int(y), int(x), int(WavePos), int(cur))
}

